# Generate an offline HTML report directly from the R results.
# KaTeX is reused as a display-only asset; it performs no statistical calculation.
make_report_R <- function(root,r,qa) {
  esc<-function(x){x<-gsub('&','&amp;',as.character(x),fixed=TRUE);x<-gsub('<','&lt;',x,fixed=TRUE);x<-gsub('>','&gt;',x,fixed=TRUE);gsub('"','&quot;',x,fixed=TRUE)}
  number<-function(x,digits=4){ifelse(x!=0&abs(x)<1e-4,formatC(x,format='e',digits=3),formatC(x,format='f',digits=digits))}
  percent<-function(x)paste0(sprintf('%.2f',100*x),'%')
  table_html<-function(headers,rows){rows<-as.matrix(rows);paste0('<table><thead><tr>',paste0('<th>',esc(headers),'</th>',collapse=''),'</tr></thead><tbody>',paste(apply(rows,1,function(row)paste0('<tr>',paste0('<td>',esc(row),'</td>',collapse=''),'</tr>')),collapse=''),'</tbody></table>')}
  bullets<-function(x)paste0('<ul>',paste0('<li>',x,'</li>',collapse=''),'</ul>')
  equation<-function(tex)paste0('<div class="math" data-math="',esc(tex),'"></div>')
  figure<-function(name,caption)paste0('<figure><img src="../figures/',name,'.png" alt="',esc(caption),'"><figcaption>',esc(caption),'</figcaption></figure>')
  `%+%` <- function(a,b)paste0(a,b)
  body<-character()
  add<-function(title,content)body<<-c(body,paste0('<section><h2>',title,'</h2>',content,'</section>'))
  add('Data preparation in R',bullets(c(
    'The original UCI archive is checked with SHA-256, then all 14 physical sensor matrices are read and summarized in R.',
    'There are 2,205 cycles, including 1,449 stable cycles. Each cycle lasts 60 seconds.',
    'The six core summaries are temperature mean and slope, flow mean, pressure SD, power mean and vibration mean. Derived CE, CP and SE channels are excluded.',
    'For inference, stable readings are averaged in 48 settings crossed with three cooler conditions. Cooler condition and recording phase remain perfectly confounded.')) %+%
    figure('01_recording_order_R','The original recording order reveals the cooler/phase alignment.'))
  means<-do.call(rbind,lapply(r$group_summaries,function(g)c(g$label,number(g$mean_raw,5))))
  add('Mean vectors',equation(r"(\bar{\mathbf x}_k=\frac{1}{48}\sum_{s=1}^{48}\mathbf x_{sk})") %+%
    bullets('The averages describe the condition profiles. Near failure has higher mean temperature and lower mean flow in this experiment.') %+%
    table_html(c('Condition',FEATURE_NAMES),means) %+%figure('02_mean_vectors_R','One common profile scale; error bars are between-setting SDs.'))
  add('Covariance and correlation',equation(r"(S_k=\frac{1}{n_k-1}\sum_s(\mathbf x_{sk}-\bar{\mathbf x}_k)(\mathbf x_{sk}-\bar{\mathbf x}_k)^T,\qquad r_{ij}=\frac{s_{ij}}{\sqrt{s_{ii}s_{jj}}})") %+%
    bullets(c('Covariance includes marginal variability and relationships between features. Correlation gives the dimensionless linear relationship.',
      paste0('For near failure, flow and pressure fluctuation have correlation ',number(r$group_summaries[[3]]$correlation[3,4],3),'. The sensor readings are strongly related, so a joint model is useful.'))) %+%
    figure('03_correlations_R','All three matrices use the same correlation scale from -1 to +1.'))
  gv<-do.call(rbind,lapply(r$group_summaries,function(g)c(g$label,number(g$log_generalized_variance),number(g$standardized_generalized_variance,6))))
  add('Generalized variance',equation(r"(GV=|S|=\prod_j\lambda_j,\qquad SGV=|S|^{1/6})") %+%
    bullets('The covariance determinant describes joint spread on the common scale. Its sixth root is about 6.1 times larger for near failure than for full efficiency.') %+%
    table_html(c('Condition','log determinant','Sixth-root generalized variance'),gv) %+%figure('04_generalized_variance_R','Comparisons use the same transformation for every group.'))
  shape<-do.call(rbind,lapply(r$distribution_checks$groups,function(g)c(LABELS[as.character(g$cooler)],number(g$skewness),number(g$kurtosis),number(g$skew_p_mc,3),number(g$kurtosis_p_mc,3))))
  add('Skewness, kurtosis and distribution checks',equation(r"(b_{1,p}=\frac{1}{n^2}\sum_{i,j}D_{ij}^3,\qquad b_{2,p}=\frac{1}{n}\sum_iD_{ii}^2)") %+%
    bullets(c('Checks are performed within each condition. Pooling three different means would create a mixture rather than test a meaningful within-condition Gaussian model.',
      'R generates its own 999 finite-sample Gaussian references at n = 48 and p = 6. The population kurtosis target is 48, but fitted finite-sample behaviour differs.',
      'The slides and this report use the same R simulation results. These checks suggest that the Gaussian model is an approximation, so we also test its predictions on separate data.')) %+%
    table_html(c('Condition','Mardia skewness','Mardia kurtosis','R skewness MC p','R kurtosis MC p'),shape) %+%
    figure('05_distribution_qq_R','Within-condition temperature Q-Q plots.') %+%figure('06_mardia_simulations_R','New reference samples generated by R; vertical lines show observed statistics.'))
  add('Maximum likelihood estimation',equation(r"(\widehat\mu=\bar{\mathbf x},\qquad \widehat\Sigma_{ML}=\frac{1}{n}\sum_i(\mathbf x_i-\bar{\mathbf x})(\mathbf x_i-\bar{\mathbf x})^T=\frac{n-1}{n}S)") %+%
    bullets(c('The Gaussian model estimates its means and covariances using maximum likelihood. Shrinkage candidates are considered only for diagnostic model selection.',
      paste0('The two-feature numerical fit uses optim(method="BFGS") with an analytical gradient. It converged with maximum parameter difference ',number(r$numerical_MLE$max_parameter_gap),' and log-likelihood gap ',number(r$numerical_MLE$objective_gap),'.'),
      'Means, log standard deviations and atanh(correlation) keep the fitted bivariate covariance valid.')) %+%
    figure('07_MLE_likelihood_R','The analytical and numerical R fits coincide.'))
  refs<-do.call(rbind,lapply(r$manova$conventional_reference,function(v)c(v$statistic,number(v$value,6),number(v$approx_F),number(v$num_df,0),number(v$den_df),number(v$p_iid))))
  hl<-r$manova$presentation_compatible_HL
  add('MANOVA with matched setting effects',equation(r"(\mathbf Y_{sk}=\alpha_s+\tau_k+\varepsilon_{sk},\qquad H_0:\tau_1=\tau_2=\tau_3)") %+%
    bullets(c(paste0('Manual SSCP matrices agree with stats::manova(). Roy = ',number(r$manova$roy,6),'; Wilks = ',number(r$manova$wilks,9),'; residual df = 94.'),
      'The joint mean profiles differ under the reference model. This is a recorded cooler/phase association, not an identified causal cooler effect.',
      'The table gives native summary.manova() approximations. Roy\'s general F reference is an upper-bound convention.')) %+%
    table_html(c('R test','Statistic','Approximate F','Numerator df','Denominator df','R reference p'),refs) %+%
    paste0('<p>Hotelling-Lawley has more than one F approximation. The slides use the native R reference above. An alternative approximation is retained for comparison with the original implementation: F = ',number(hl$approx_F),', denominator df = ',number(hl$den_df),', p = ',number(hl$p_iid),'. The trace and conclusion agree. Both references are explicitly labelled.</p>'))
  hotelling<-do.call(rbind,lapply(r$hotelling,function(h)c(paste(LABELS[as.character(h$to)],'minus',LABELS[as.character(h$from)]),number(h$T2,3),number(h$p_iid),number(h$p_holm_iid),number(h$sign_flip_p,3))))
  add('Paired Hotelling T-squared',equation(r"(T^2=48\bar{\mathbf d}^{T}S_d^{-1}\bar{\mathbf d},\qquad F=\frac{48-6}{6(48-1)}T^2\sim F_{6,42})") %+%
    bullets(c('Each comparison uses 48 matched six-feature difference vectors. The three comparisons receive Holm adjustment.',
      'The F reference assumes independent Gaussian differences. Sign-flip and circular-block sensitivities retain matching but do not resolve the phase limitation.')) %+%
    table_html(c('Difference','T2','iid p','Holm iid p','Sign-flip p'),hotelling) %+%
    figure('09_Hotelling_intervals_R','R pointwise temperature-difference intervals with block lengths 1, 4 and 8.') %+%
    figure('10_Hotelling_mean_region_R','The confidence ellipse describes the mean difference, not individual future readings.'))
  bm<-r$covariance_tests$box_m;lr<-r$covariance_tests$gaussian_lrt
  add('Covariance equality tests',equation(r"(M=(N-g)\log|S_P|-\sum_k(n_k-1)\log|S_k|,\qquad (1-c)M\ \dot\sim\ \chi^2_{42})") %+%
    bullets(c(paste0('Box M = ',number(bm$M),'; correction = ',number(bm$correction,6),'; corrected statistic = ',number(bm$chi2),'; p = ',number(bm$p_iid),'.'),
      paste0('The Gaussian ML covariance likelihood ratio is ',number(lr$LR),' with 42 df; p = ',number(lr$p_iid),'. It uses ML divisors n, whereas Box M uses n - 1 covariance weights.'),
      'Both challenge exact covariance equality. Model prediction is assessed separately; a shared covariance can still win grouped validation.')) %+%
    figure('11_covariance_null_R','The matched Gaussian sensitivity assumes a 50% common component; this is an assumption, not an estimated dependence correction.'))
  add('Partial correlation and explanatory regression',equation(r"(R=Y-X\widehat B,\qquad r_{ij\cdot X}=\operatorname{Corr}(R_i,R_j))") %+%
    bullets(c('Each feature is adjusted for additive categorical cooler/phase, valve, pump and accumulator associations using lm.fit().',
      paste0('Temperature-vibration correlation changes from ',number(r$partial_regression$raw_correlation[1,6],3),' to ',number(r$partial_regression$adjusted_correlation[1,6],3),' after adjustment.'),
      paste0('The explanatory temperature regression R2 is ',number(r$partial_regression$temperature_R2_in_sample,6),'. This is in-sample interpretation, not diagnostic validation. Recorded component labels never enter the diagnostic score.'))) %+%
    figure('12_partial_correlations_R','Raw correlations and correlations between adjusted residuals.'))
  sim<-do.call(rbind,lapply(names(r$manova$resampling),function(name){v<-r$manova$resampling[[name]];c(name,v$B,number(v$critical_95,5),number(v$p_mc,3))}))
  add('Simulation and resampling in R',equation(r"(\widehat p=\frac{1+\#\{T_b^*\geq T_{obs}\}}{B+1})") %+%
    bullets(c('Independent Gaussian null simulations are separate from matched wild resampling. The restricted wild procedure uses null residuals and one sign for the entire setting block.',
      'The full-residual null-centred variant is labelled separately. Circular blocks of length 1, 4 and 8 are sensitivities, not a guarantee of independence.',
      'The stable holdout setting bootstrap is [100%, 100%] because every observed setting is correct. It cannot prove zero future error.')) %+%
    table_html(c('Reference','Draws','95% Roy cutoff','Monte Carlo p'),sim) %+%figure('08_MANOVA_null_R','Roy under three explicitly specified R null-generation procedures.'))
  metrics<-do.call(rbind,lapply(names(r$models),function(k)c(k,r$models[[k]]$alpha,percent(r$predictive_results[[k]]$intact$balanced_accuracy),percent(r$predictive_results[[k]]$TS2_unavailable$balanced_accuracy))))
  add('R model training and final held-out evaluation',bullets(c('The 36 development settings supply 1,089 stable cycles. Six-fold cross-validation keeps each setting together and fits the scaler inside each fold.',
      'The candidate families are diagonal, shared and separate Gaussian covariance with six shrinkage values, plus a temperature-only baseline. The objective averages intact and complete-TS2-outage log loss.',
      'R independently selects shared covariance with alpha = 0. The model specification is saved before the 12 held-out settings are evaluated.',
      'The R fold plan uses its own deterministic group-balancing tie rule, and is saved for inspection. Folds can differ from the earlier implementation; the selected model and all final confusion matrices agree.')) %+%
    equation(r"(\log q_k=\log\pi_k-\tfrac12[p\log(2\pi)+\log|\Sigma_k|+(z-\mu_k)^T\Sigma_k^{-1}(z-\mu_k)])") %+%
    table_html(c('Model','Selected alpha','Intact balanced accuracy','Without TS2 balanced accuracy'),metrics) %+%
    figure('13_model_comparison_R','Final results from models fitted in R.') %+%
    equation(r"(z_O\mid k\sim N(\mu_{k,O},\Sigma_{k,OO}))") %+%
    bullets('Removing TS2 removes both mean and slope. The score uses the observed mean subvector and covariance submatrix, not a zero-filled sensor reading.') %+%
    figure('14_outage_confusion_R','R predictions on the same 360 held-out stable cycles.'))
  add('Transition and input-offset stress checks',bullets(c(paste0('The separate transition subset contains ',r$transition_stress$n,' cycles from held-out settings. Accuracy is ',percent(r$transition_stress$accuracy),' and balanced accuracy is ',percent(r$transition_stress$balanced_accuracy),'.'),
    'Transition cycles were never used for fitting or selection. They show why the perfect stable-cycle result is not a guarantee of future performance.',
    'Artificial offsets change TS2 mean only. They are input sensitivity experiments, not physical process-temperature changes.')) %+%
    figure('15_sensor_offset_R','Artificial calibration offsets, computed in R.') %+%
    figure('16_transition_stress_R','Confusion and recall on the separately held-out transition cycles.'))
  add('Verification and files',bullets(c(paste0(qa$passed,' native R checks passed, including independent covariance, likelihood, MANOVA, Mardia, T2 and missing-input checks.'),
    paste0('R-trained predictions were compared with all ',qa$browser_oracle_cases,' saved browser oracle cases. Maximum probability difference: ',number(qa$browser_max_probability_difference),'.'),
    'The slide data, four fitted models and displayed simulation values are exported directly from these R results.',
    'The R scripts never invoke Python. The original result files are read only in post-fit verification, not in fitting or model selection.')) %+%
    '<ul><li><a href="analysis_R.json">Full R results</a></li><li><a href="development_cv_R.csv">R grouped cross-validation</a></li><li><a href="holdout_predictions_R.csv">R holdout predictions</a></li><li><a href="../models/trained_gaussian_model.rds">Trained R model</a></li><li><a href="QA_R.json">R verification record</a></li><li><a href="../../R_README.md">RStudio instructions</a></li></ul>')
  add('References','<ul><li>Helwig, Pignanelli and Schuetze, UCI 447, CC BY 4.0: <a href="https://doi.org/10.24432/C5CW21">10.24432/C5CW21</a>.</li><li>R documentation: <a href="https://search.r-project.org/R/refmans/stats/html/summary.manova.html">summary.manova()</a> and <a href="https://stat.ethz.ch/R-manual/R-patched/library/stats/html/optim.html">optim()</a>.</li><li>Mardia (1970): <a href="https://doi.org/10.1093/biomet/57.3.519">10.1093/biomet/57.3.519</a>.</li><li>Alternative Hotelling-Lawley reference formula: <a href="https://www.statsmodels.org/stable/_modules/statsmodels/multivariate/multivariate_ols.html">documented multivariate_stats source</a>. Implemented independently in R for compatibility checking.</li></ul>')
  header<-paste0('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hydraulic Cooler Analysis in R</title><link rel="stylesheet" href="../../dist/vendor/katex.min.css"><style>body{margin:0;color:#173344;background:#fff;font:17px/1.65 Arial,sans-serif}main{max-width:1100px;margin:45px auto;padding:0 28px}h1{line-height:1.2;font-size:36px}h2{font-size:26px;line-height:1.3;margin-top:45px}li{margin-bottom:10px}a{color:#176b73}table{border-collapse:collapse;width:100%;font-size:13px;margin:22px 0}td,th{text-align:left;padding:9px;border-bottom:1px solid #dbe3e4}figure{margin:25px 0}img{width:100%;height:auto}figcaption{font-size:13px;color:#526d7a}.math{overflow:auto;margin:25px 0}section{margin-bottom:35px}footer{font-size:13px;margin:50px 0;color:#526d7a}</style></head><body><main><h1>Multivariate Statistical Diagnosis of Hydraulic Cooler Faults</h1><p>Statistics, simulation and model training in R. Generated using ',esc(r$R_version),'.</p><p>The 14-slide presentation uses the results and models calculated in R. Open R/Presentation_Demo.R to follow the main calculations alongside the slides.</p>')
  footer<-'<footer>Computed from the original UCI measurements. The experiment concerns one rig; cooler and recording phase coincide.</footer></main><script src="../../dist/vendor/katex.min.js"></script><script>document.querySelectorAll("[data-math]").forEach(e=>katex.render(e.dataset.math,e,{displayMode:true,throwOnError:false}));</script></body></html>'
  writeLines(c(header,body,footer),file.path(root,'R/results/R_Analysis_Report.html'),useBytes=TRUE)
  message('R report generated: R/results/R_Analysis_Report.html')
}
